/// <summary>
/// Extension of class <c>SalesConfirmDP</c>
/// </summary>
[ExtensionOf(classStr(SalesConfirmController))]
internal final class METSalesConfirmController_Extension
{
}

Method.Source:
    /// <summary>
    /// Gets the sales confirmation document title.
    /// </summary>
    /// <returns>
    /// The document title.
    /// </returns>
    protected str documentTitle()
    {
        str documentTitle = next documentTitle();

        if (documentTitle == literalStr("@SYS12529"))
        {
            documentTitle = literalStr("@MET:SalesOrderConfirmation");
        }

        return documentTitle;
    }

/// <summary>
/// Sets the <c>SRSReportParameters</c> values in the report contract. Also used to set certain other assignments that is used in the data provider class.
/// </summary>
protected void modifyContract()
{
    next modifyContract();
    SalesConfirmContract salesConfirmContract = contract as SalesConfirmContract;
    salesConfirmContract.parmMetcashReportName(this.parmReportName());
}
